maze_chase.skill_source:
import math

class GeneratedArenaSkill:
    def __init__(self):
        self.t = 0

    def compute_action(self, obs):
        self.t += 1
        d = obs.get("danger", 0)
        e = obs.get("escape")
        if d >= 0.5 and e:
            return {"move": [float(e[0]), float(e[1])], "buttons": [], "hold_ms": 0}
        sx, sy = obs["self"]
        items = obs.get("items") or []
        best = None
        bd = 999.0
        for i in range(6):
            if i < len(items):
                it = items[i]
                dx = it[0] - sx
                dy = it[1] - sy
                q = dx * dx + dy * dy
                if q < bd:
                    bd = q
                    best = it
        if best:
            dx = best[0] - sx
            dy = best[1] - sy
            if abs(dx) >= abs(dy):
                m = [1.0 if dx > 0 else -1.0, 0.0]
            else:
                m = [0.0, 1.0 if dy > 0 else -1.0]
            return {"move": m, "buttons": [], "hold_ms": 0}
        return {"move": [0.0, 0.0], "buttons": [], "hold_ms": 0}

key_caves.skill_source:
import math

class GeneratedArenaSkill:
    def __init__(self):
        self.t = 0
        self.dir = 1.0
        self.px = 0.0
        self.py = 0.0
        self.stuck = 0

    def compute_action(self, obs):
        self.t += 1
        s = obs.get("self") or [0.5, 0.5]
        sx = float(s[0])
        sy = float(s[1])
        danger = float(obs.get("danger") or 0.0)
        esc = obs.get("escape")
        if danger >= 0.5 and esc:
            ex = float(esc[0])
            mvx = 1.0 if ex > 0.0 else -1.0
            if abs(ex) < 0.2:
                mvx = self.dir
            return {"move": [mvx, 0.0], "buttons": ["jump"], "hold_ms": 0}
        dx = sx - self.px
        dy = sy - self.py
        moved = math.sqrt(dx * dx + dy * dy)
        if moved < 0.0004:
            self.stuck += 1
        else:
            self.stuck = 0
        if self.stuck > 40:
            self.stuck = 0
            self.dir = -1.0 * self.dir
        self.px = sx
        self.py = sy
        if self.t % 240 < 120:
            self.dir = 1.0
        else:
            if sx > 0.85:
                self.dir = 1.0
            elif sx < 0.15:
                self.dir = 1.0
        mv = 1.0 if self.dir > 0.0 else -1.0
        buttons = []
        cyc = self.t % 30
        if cyc == 0 or cyc == 10:
            buttons = ["jump"]
        elif cyc == 20:
            buttons = ["attack"]
        items = obs.get("items") or []
        if items:
            best = 999.0
            bx = 0.0
            by = 0.0
            for i in range(len(items)):
                it = items[i]
                ix = float(it[0]) - sx
                iy = float(it[1]) - sy
                d = abs(ix) + abs(iy)
                if d < best:
                    best = d
                    bx = ix
                    by = iy
            if best < 0.25:
                if abs(bx) > 0.01:
                    mv = 1.0 if bx > 0.0 else -1.0
        return {"move": [mv, 0.0], "buttons": buttons, "hold_ms": 0}
